package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;
import tools.jackson.databind.node.*;

class SourceValuePartialStageContextTest {
    SourceDedupResolvedStageResultTest f;final LocalDate day=LocalDate.of(2026,1,1);
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup(int count)throws Exception {f=new SourceDedupResolvedStageResultTest(){@Override GenerationJdbcStoreTest database(){return SourceValuePartialStageContextTest.this.database();}};f.setup(count);}
    Instant cutoff(){return f.f.clock.instant().plusSeconds(60);}
    FrozenSourceDedupDependency dependency(){var result=SourceDedupStageResult.createResolved(f.snapshot(f.ref));return FrozenSourceDedupDependency.create(result,f.f.clock.instant(),cutoff());}
    String context(boolean collection){return SourceValueStageContext.create(dependency(),day,cutoff(),collection);}
    ObjectNode snapshot(String context){var original=CanonicalJson.parse(context);var node=JsonMapper.shared().createObjectNode().put("stage","news_value").put("business_date",day.toString()).put("cutoff",cutoff().toString());for(String field:List.of(FrozenSourceDedupDependency.FIELD,"coverage_state"))node.set(field,original.get(field).deepCopy());node.set("missing",JsonMapper.shared().valueToTree(SourceValueStageContext.partialSnapshotMissing(context,day,cutoff())));return node;}
    @Test void sparseFailureHasExactOriginalReasonAndDoesNotInventCollectionPartial()throws Exception {
        setup(201);f.applied(0);f.terminal(1,"failed");f.applied(2);int before=f.f.db.count("1=1");String raw=context(false);var node=CanonicalJson.parse(raw);assertEquals("source-value-stage-context-v2",node.get("schema_version").asText());assertEquals("partial",node.get("coverage_state").asText());assertEquals(1,node.get("missing").size());assertEquals("source_fragment",node.get("missing").get(0).get("kind").asText());assertEquals(f.plan.chunks().get(1).rootId(),node.get("missing").get(0).get("id").asText());assertEquals("dedup_failed",node.get("missing").get(0).get("reason").asText());assertEquals(201,node.get(FrozenSourceDedupDependency.FIELD).get("stage_result").get("decisions").size());assertEquals(100,node.get(FrozenSourceDedupDependency.FIELD).get("stage_result").get("unapplied_member_count").asInt());assertEquals(raw,SourceValueStageContext.readPartial(raw,day,cutoff()));assertEquals(raw,SourceValueStageContext.fromPartialSnapshot(snapshot(raw)));assertEquals(before,f.f.db.count("1=1"));
    }
    @Test void allFourOriginalFailureReasonsAndOptionalCollectionAreExactAndStable()throws Exception {
        setup(1);for(String state:List.of("failed","cancelled","discarded","superseded")){f.terminal(0,state);var alone=CanonicalJson.parse(context(false));assertEquals(1,alone.get("missing").size());assertEquals("dedup_"+state,alone.get("missing").get(0).get("reason").asText());assertEquals(1,alone.get(FrozenSourceDedupDependency.FIELD).get("stage_result").get("unapplied_member_count").asInt());String combined=context(true);var node=CanonicalJson.parse(combined);assertEquals(2,node.get("missing").size());assertEquals("source_fragment",node.get("missing").get(0).get("kind").asText());assertEquals("source_run",node.get("missing").get(1).get("kind").asText());assertEquals("fictional-run",node.get("missing").get(1).get("id").asText());assertEquals("collection_partial",node.get("missing").get(1).get("reason").asText());assertEquals(combined,SourceValueStageContext.readPartial(combined,day,cutoff()));}
    }
    @Test void legacyReadersRemainClosedAndScopeAcceptsExplicitValidatedPartialContext()throws Exception {
        setup(1);f.terminal(0,"failed");String raw=context(false);assertThrows(RuntimeException.class,()->SourceValueStageContext.read(raw,day,cutoff()));assertThrows(RuntimeException.class,()->SourceValueStageContext.fromSnapshot(snapshot(raw)));assertDoesNotThrow(()->new SourcePartitionPlanner.Scope(day,cutoff(),new FrozenGenerationSettings(0,List.of(),List.of()),raw));assertThrows(RuntimeException.class,()->SourceValueStageContext.fromPartialSnapshot(snapshot(raw).put("stage","news_dedup")));
    }
    @Test void unknownOmittedDuplicateAndReplacedMissingItemsCannotHideOriginalFailures()throws Exception {
        setup(201);f.terminal(0,"failed");f.terminal(1,"cancelled");f.applied(2);var valid=(ObjectNode)CanonicalJson.parse(context(true));
        for(String mode:List.of("missing","duplicate","reason","id","kind","extra","coverage","version","order","collection")){var changed=valid.deepCopy();var missing=(ArrayNode)changed.get("missing");switch(mode){case "missing"->missing.remove(0);case "duplicate"->missing.add(missing.get(0).deepCopy());case "reason"->((ObjectNode)missing.get(0)).put("reason","dedup_superseded");case "id"->((ObjectNode)missing.get(0)).put("id","b".repeat(64));case "kind"->((ObjectNode)missing.get(0)).put("kind","source_item");case "extra"->((ObjectNode)missing.get(0)).put("extra",true);case "coverage"->changed.put("coverage_state","complete");case "version"->changed.put("schema_version","source-value-stage-context-v1");case "order"->{var first=missing.get(0).deepCopy();missing.set(0,missing.get(1));missing.set(1,first);}case "collection"->((ObjectNode)missing.get(missing.size()-1)).put("id","fictional-other-run");}assertThrows(RuntimeException.class,()->SourceValueStageContext.readPartial(canonical(changed),day,cutoff()),mode);}
        var fields=valid.deepCopy();fields.put("extra",true);assertThrows(RuntimeException.class,()->SourceValueStageContext.readPartial(canonical(fields),day,cutoff()));assertThrows(RuntimeException.class,()->SourceValueStageContext.readPartial(canonical(valid)+" ",day,cutoff()));var nativeSnapshot=snapshot(canonical(valid));nativeSnapshot.putArray("missing").add("fictional-wrong");assertThrows(RuntimeException.class,()->SourceValueStageContext.fromPartialSnapshot(nativeSnapshot));var typedSnapshot=snapshot(canonical(valid));typedSnapshot.set("missing",valid.get("missing"));assertThrows(RuntimeException.class,()->SourceValueStageContext.fromPartialSnapshot(typedSnapshot));assertThrows(UnsupportedOperationException.class,()->SourceValueStageContext.partialSnapshotMissing(canonical(valid),day,cutoff()).clear());
    }
    @Test void dayCutoffCapacityAndOriginalCompleteV1CannotBeReplacedByPartialContext()throws Exception {
        setup(1);f.terminal(0,"failed");String raw=context(false);var dependency=dependency();assertThrows(RuntimeException.class,()->SourceValueStageContext.readPartial(raw,day.plusDays(1),cutoff()));assertThrows(RuntimeException.class,()->SourceValueStageContext.readPartial(raw,day,f.f.clock.instant().minusNanos(1000)));assertThrows(RuntimeException.class,()->SourceValueStageContext.readPartial(raw,day,cutoff().plusNanos(1)));assertThrows(GenerationFlowService.CapacityGuarded.class,()->SourceValueStageContext.createPartialWithinCapacity(dependency,day,cutoff(),false,1));
        for(int size:List.of(0,SourceValueStageContext.PARTIAL_MAX_BYTES+1))assertThrows(RuntimeException.class,()->SourceValueStageContext.createPartialWithinCapacity(dependency,day,cutoff(),false,size));var legacy=new NewsValueSourcePlanBuilderTest();var zero=legacy.fixture(0);String old=SourceValueStageContext.create(zero.dependency(),legacy.day,legacy.cutoff,false);assertEquals("source-value-stage-context-v1",CanonicalJson.parse(old).get("schema_version").asText());assertEquals(old,SourceValueStageContext.read(old,legacy.day,legacy.cutoff));assertThrows(RuntimeException.class,()->SourceValueStageContext.readPartial(old,legacy.day,legacy.cutoff));
    }
    @Test void legacyV1AndZeroPreserveTheExistingGoldenBytes() {
        var fixture=new NewsValueSourcePlanBuilderTest();var expected=Map.of("0:false","568d027dfce5fba5708881eaa57e75afb63a18f00ba1ffc2370d5e504f9290d4","0:true","66ef671f839feccd1fd962c1b833570e33f28c1ddaf7d314a19930c862459798","203:false","8657f169c76ac9493d2eb5c9a1f96dcf309be3dbf853134df414863e3988f2dc","203:true","4ddb26441e2fc9aefaa5be976ecefb6c3366e35dcedf0e1383fb85106833f9d5");for(int count:List.of(0,203)){var original=fixture.fixture(count);for(boolean partial:List.of(false,true)){String raw=SourceValueStageContext.create(original.dependency(),fixture.day,fixture.cutoff,partial);assertEquals(expected.get(count+":"+partial),CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(raw)));assertEquals(raw,SourceValueStageContext.read(raw,fixture.day,fixture.cutoff));}}
    }
    static String canonical(tools.jackson.databind.JsonNode node){return new String(CanonicalJson.bytes(node),java.nio.charset.StandardCharsets.UTF_8);}
}
